static void ttm_tt_init_fields ( struct ttm_tt * ttm , struct ttm_buffer_object * bo , uint32_t page_flags , enum ttm_caching caching , unsigned long extra_pages ) { ttm -> num_pages = ( PAGE_ALIGN ( bo -> base . size ) >> PAGE_SHIFT ) + extra_pages ; ttm -> caching = ttm_cached ; ttm -> page_flags = page_flags ; ttm -> dma_address = NULL ; ttm -> swap_storage = NULL ; ttm -> sg = bo -> sg ; } 